// Normaliza el payload crudo de Wazuh / OPNsense / Suricata.
const body = $json.body ?? $json;
const rule = body.rule ?? {};
const agent = body.agent ?? {};
const data = body.data ?? {};

const level = Number(rule.level ?? body.rule_level ?? body.level ?? 0);
let severity = body.severity;
if (!severity) {
  if (level >= 12) severity = 'critical';
  else if (level >= 10) severity = 'high';
  else if (level >= 7) severity = 'medium';
  else if (level >= 4) severity = 'low';
  else severity = 'info';
}
severity = String(severity).toLowerCase();
const allowed = ['critical', 'high', 'medium', 'low', 'info'];
if (!allowed.includes(severity)) severity = 'medium';

const srcIp = data.srcip ?? data.src_ip ?? body.src_ip ?? body.srcip ?? null;
const dstIp = data.dstip ?? data.dst_ip ?? body.dst_ip ?? body.dstip ?? null;
const description = String(rule.description ?? body.description ?? body.message ?? 'Alerta sin descripción').slice(0, 2000);
const source = String(body.source ?? 'wazuh');
const externalId = String(body.id ?? body.alert_id ?? body.event_id ?? '');
const ruleId = String(rule.id ?? body.rule_id ?? '');
const occurredAt = body.timestamp ?? body.occurred_at ?? new Date().toISOString();

const tags = [];
const lower = description.toLowerCase();
if (/brute|fuerza bruta|failed password/.test(lower)) tags.push('bruteforce');
if (/ransom|cifrado|locked/.test(lower)) tags.push('ransomware');
if (/scan|escaneo/.test(lower)) tags.push('recon');
if (/powershell|cmd\.exe|wmic/.test(lower)) tags.push('execution');
if (/sql|xss|traversal|cve-|exploit/.test(lower)) tags.push('web-exploit');
if (/dns|domain|dominio/.test(lower)) tags.push('dns');
if (/firewall|block|deny/.test(lower)) tags.push('firewall');
if (severity === 'critical' || severity === 'high') tags.push('high-impact');

const crypto = require('crypto');
const window = Math.floor(new Date(occurredAt).getTime() / (15 * 60 * 1000));
const fingerprint = crypto.createHash('sha256')
  .update([source, ruleId, srcIp ?? '', dstIp ?? '', externalId, window].join('|'))
  .digest('hex');

const record = {
  external_id: externalId || null,
  source,
  rule_id: ruleId || null,
  rule_level: level || null,
  description,
  src_ip: srcIp,
  dst_ip: dstIp,
  dst_port: data.dstport ?? body.dst_port ?? null,
  protocol: data.protocol ?? body.protocol ?? null,
  agent_name: agent.name ?? body.agent_name ?? null,
  asset_criticality: Math.min(Math.max(Number(body.asset_criticality ?? agent.criticality ?? 3), 1), 5),
  severity,
  fingerprint,
  raw_payload: body,
  tags: tags.join('|'),
  occurred_at: occurredAt,
};

return [{
  json: {
    ...record,
    passes_filter: ['critical', 'high', 'medium'].includes(severity),
    payload_b64: Buffer.from(JSON.stringify(record)).toString('base64'),
  },
}];

// Prepara el resultado del agente para persistirlo como un único parámetro JSON (base64).
const t = $json;
const alertId = $('Persistir alerta').item.json.id;
const payload = {
  alert_id: alertId,
  verdict: t.verdict ?? 'inconclusive',
  severity: t.severity ?? 'medium',
  confidence: Number(t.confidence ?? 0.5),
  summary: String(t.summary ?? 'Triaje sin resumen').slice(0, 1200),
  reasoning: t.reasoning ?? null,
  recommended_actions: t.recommended_actions ?? [],
  mitre_techniques: t.mitre_techniques ?? [],
  model: t.model ?? 'langchain',
  prompt_version: t.prompt_version ?? 'v1.2.0',
  latency_ms: Number(t.latency_ms ?? 0),
  status: t.status ?? 'completed',
  needs_human: Boolean(t.needs_human),
  fallback_used: Boolean(t.fallback_used),
  raw_response: t,
};
return [{
  json: {
    alert_id: alertId,
    severity: payload.severity,
    verdict: payload.verdict,
    summary: payload.summary,
    status: payload.status,
    payload_b64: Buffer.from(JSON.stringify(payload)).toString('base64'),
  },
}];
